package hmgapi.hook;public class Dispatch {public static void bind(MethodHook hook,Object adapter,int position,android.view.View view,Runnable original)throws Throwable {MethodHook.Param p=new MethodHook.Param(null,adapter,new Object[]{position,view,null});hook.beforeHookedMethod(p);original.run();p.setResult(view);hook.afterHookedMethod(p);}public static void destroy(MethodHook hook,Object activity)throws Throwable {hook.beforeHookedMethod(new MethodHook.Param(null,activity,new Object[0]));}}
